"""What has shipped, what is owed, and what a fulfil run can ship."""

from __future__ import annotations

import datetime
from dataclasses import dataclass
from types import SimpleNamespace
from typing import Dict, List

from .movements import Movement, in_count_order
from .orders import Order


def shipped_so_far(order: Order, movements: List[Movement]) -> Dict[str, int]:
    """Per SKU of the order: units already shipped (capped at the quantity ordered)."""
    note = "order %s" % order.id
    sent: Dict[str, int] = {}
    for move in movements:
        if move.quantity < 0 and move.note == note:
            sent[move.sku] = sent.get(move.sku, 0) - move.quantity
    return {sku: min(quantity, sent.get(sku, 0)) for sku, quantity in order.lines}


def order_status(order: Order, shipped: Dict[str, int]) -> str:
    """``complete`` when nothing is owed, ``open`` when nothing shipped, else ``partial``."""
    if all(shipped.get(sku, 0) >= quantity for sku, quantity in order.lines):
        return "complete"
    if all(shipped.get(sku, 0) == 0 for sku, _ in order.lines):
        return "open"
    return "partial"


def shipped_basket(order: Order, shipped: Dict[str, int]):
    """A pseudo order of what has shipped (lines with nothing shipped left out)."""
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped.get(sku, 0) > 0]
    return SimpleNamespace(lines=lines)


@dataclass(frozen=True)
class Shipment:
    sku: str
    shipped: int
    backordered: int


def available_on(sku: str, date: datetime.date, movements: List[Movement]) -> int:
    """Units of ``sku`` that can leave on ``date`` without any later balance going below zero."""
    balance = 0
    on_date = 0
    later_low = None
    for move in in_count_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            on_date = balance
        elif later_low is None or balance < later_low:
            later_low = balance
    if later_low is not None:
        on_date = min(on_date, later_low)
    return max(0, on_date)


def plan_fulfil(order: Order, date: datetime.date, movements: List[Movement]) -> List[Shipment]:
    """What to ship for each order line on ``date``."""
    done = shipped_so_far(order, movements)
    plan = []
    for sku, quantity in order.lines:
        owed = quantity - done[sku]
        ship = max(0, min(owed, available_on(sku, date, movements)))
        plan.append(Shipment(sku, ship, owed - ship))
    return plan
