"""Stock levels, low stock and history."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List

from .catalog import Product
from .movements import Movement, in_count_order


def stock_levels(catalog: Dict[str, Product], movements: List[Movement]) -> Dict[str, int]:
    """Quantity on the shelf for every product in the catalogue, by SKU."""
    levels = {sku: 0 for sku in sorted(catalog)}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def status(onhand: int, reorder: int) -> str:
    """``out`` at zero, ``low`` at or under the reorder level, else ``ok``."""
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    """How many to buy to get back to twice the reorder level (at least 1)."""
    return max(1, 2 * reorder - onhand)


@dataclass(frozen=True)
class HistoryEntry:
    date: object
    delta: int
    balance: int
    note: str


def history(sku: str, movements: List[Movement]) -> List[HistoryEntry]:
    """Movements of one SKU in counting order, with the running balance."""
    entries = []
    balance = 0
    for move in in_count_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        entries.append(HistoryEntry(move.date, move.quantity, balance, move.note))
    return entries


def format_delta(quantity: int) -> str:
    return "%+d" % quantity
