        return buffer.getvalue()
    return lines_out([
        "%s %s %s %s %d/%d %s %s" % (r["order"], r["date"], r["customer"], r["status"],
                                     r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    ])


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
