import os
import subprocess
import sys
import tempfile
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "src")

CATALOG = """\
# SKU   | name            | price | reorder | tax
AB-100 | Garden gnome     | 12.50 | 5       | standard
cd-205 | Seed packet, mix | 1.99  | 40      | reduced
EF-310 | Gift voucher     | 25.00 | 0
"""

MOVEMENTS = """\
2024-03-01 AB-100 +20 first delivery
2024-03-04 ab-100 -3 order SO-1001
2024-03-05 CD-205 40
"""

ORDERS = """\
SO-1001 2024-03-03 acme AB-100*12,CD-205*3
SO-1002 2024-03-09 Bea ab-100*2
"""


def run_cli(args, cwd=None, stdin=None):
    env = dict(os.environ)
    env["PYTHONPATH"] = SRC + os.pathsep + env.get("PYTHONPATH", "")
    env["PYTHONIOENCODING"] = "utf-8"
    return subprocess.run(
        [sys.executable, "-m", "stockroom"] + list(args),
        cwd=cwd, env=env, stdin=subprocess.DEVNULL if stdin is None else stdin,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE,
    )


class ShopCase(unittest.TestCase):
    """A temp folder holding the three files; ``self.run_cli`` runs the command there."""

    catalog = CATALOG
    movements = MOVEMENTS
    orders = ORDERS

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.dir = self._tmp.name
        for name, content in (("catalog.txt", self.catalog), ("movements.txt", self.movements),
                              ("orders.txt", self.orders)):
            if content is not None:
                self.write(name, content)

    def path(self, name):
        return os.path.join(self.dir, name)

    def write(self, name, content):
        data = content if isinstance(content, bytes) else content.encode("utf-8")
        with open(self.path(name), "wb") as handle:
            handle.write(data)

    def read(self, name):
        with open(self.path(name), "rb") as handle:
            return handle.read()

    def run_cli(self, *args):
        return run_cli(args, cwd=self.dir)

    def ok(self, *args):
        result = self.run_cli(*args)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stderr, b"")
        return result.stdout.decode("utf-8")

    def fail(self, code, *args):
        result = self.run_cli(*args)
        self.assertEqual(result.returncode, code, result.stderr)
        self.assertEqual(result.stdout, b"")
        self.assertNotEqual(result.stderr, b"")
        return result.stderr.decode("utf-8")
