        error = ParseError(2, "boom", "catalog.txt")
        self.assertEqual(str(error), "catalog.txt: line 2: boom")
        clone = pickle.loads(pickle.dumps(error))
        self.assertEqual((clone.line, clone.filename, str(clone)), (2, "catalog.txt", str(error)))

